// Üretilen dosya: tool/ozgun/uret.py. Sanat · Dekoratif sanatlar: seramik, cam, tekstil, mobilya, kuyumculuk (kolay).
const ozArt14Kolay = <(String, String, List<String>, String)>[
  ('Kum, soda ve kireçten yapılan sıradan camda soda (sodyum karbonat) hangi işlevi görür?', 'Kuvarsın erime sıcaklığını düşürür', ['Camı renklendirir', 'Camın kırılma indisini artırır', 'Camın üzerindeki baloncukları büyütür'], 'Saf kuvars yaklaşık 1700 °C\'de erir; soda katılınca karışım çok daha düşük ısıda eritilebilir. Kireç ise camı suda çözünmeye karşı dayanıklı kılar.'),
  ('Sodalı camın suda yavaş yavaş çözünmesini önlemek için karışıma eklenen kararlılaştırıcı madde hangisidir?', 'Kireç', ['Kobalt oksit', 'Potasyum nitrat', 'Kurşun sülfür'], 'Yalnız kum ve soda ile yapılan cam suda çözünür hâle gelir; kireç eklenince cam kararlı ve dayanıklı olur.'),
  ('Londra\'daki British Museum\'da bulunan Portland Vazosu, hangi cam işleme türünün Roma çağındaki başyapıtı sayılır?', 'Cameo (kabartma oyma) cam', ['Vitray', 'Pâte de verre', 'Köpüklü cam'], 'Koyu mavi camın üzerine bindirilmiş beyaz cam tabaka, kabartma figürler kalacak biçimde oyulmuştur; bu teknik cameo cam olarak anılır.'),
  ('Cam hamuruna kobalt oksit katıldığında hangi renk elde edilir?', 'Derin mavi', ['Zümrüt yeşili', 'Altın sarısı', 'Opak beyaz'], 'Kobalt, cam renklendirmede en etkili mavi kaynaktır; çok az miktarı bile koyu mavi verir.'),
  ('Cam üretiminde \'cullet\' olarak adlandırılan kırık cam parçaları fırına neden eklenir?', 'Daha düşük ısıda erime sağladığı ve geri kazanım sunduğu için', ['Camı opak ve süt beyazı yapıp ışık geçirgenliğini azalttığı için', 'Camın rengini tamamen silip tüm cam türlerini aynı kıldığı için', 'Camın yoğunluğunu azalttığı için'], 'Kırık cam hammaddeden daha kolay erir, enerji tasarrufu sağlar ve geri dönüşümü mümkün kılar.'),
  ('Alastair Pilkington\'ın 1950\'lerde geliştirdiği \'float cam\' yönteminde erimiş cam hangi ortam üzerinde yayılarak düz levha biçimini alır?', 'Erimiş kalay banyosu', ['Soğuk su havuzu', 'Cıva yatağı', 'Dökme demir tabla'], 'Cam, erimiş kalayın üzerinde yüzer; yüzey kendiliğinden düz ve pürüzsüz olur. Bugün pencere camının büyük bölümü bu yolla üretilir.'),
  ('Cam parçacıkları kalıba doldurulup fırında eritilerek şekillendirilen ve Fransız Art Nouveau ustalarınca yaygınlaştırılan opak, boyalı camsı hamur tekniğine ne ad verilir?', 'Pâte de verre', ['Lampwork', 'Sgraffito', 'Grisaille'], 'Pâte de verre, öğütülmüş cam hamurunun kalıpta pişirilmesidir. Amalric Walter ve Gabriel Argy-Rousseau bu tekniğin tanınmış ustalarıdır.'),
  ('Bir cam sanatçısı, cam çubukları gaz alevinde ısıtarak küçük boncuklar ve figürler üretiyor. Bu tekniğin adı nedir?', 'Lampwork', ['Kıl yontma', 'Mozaik kesme', 'Kum püskürtme'], 'Alev işinde çubuk cam, masa başı brülörde yumuşatılır ve elle biçimlendirilir. Boncuk ve minyatür objelerde yaygındır.'),
  ('Camın yüzeyine hidroflorik asitle oyularak desen verilmesi işlemi hangi ada sahiptir?', 'Asitle dağlama', ['Tavlama', 'Katmanlama', 'Sırlama'], 'Cam, asit etkisiyle korunmayan yerlerinden aşınır. Emile Gallé bu yöntemi renkli katmanlı camlarda ustalıkla kullanmıştır.'),
  ('Cam yapımında uzun süredir uygulanan yöntem gereği camın içindeki hava kabarcıklarını gidermek için sıcak hamurun bir süre bekletilmesi aşamasına ne denir?', 'Berraklaştırma', ['Gaffing', 'Temperleme', 'Sandblasting'], 'Fining sırasında kabarcıklar yüzeye çıkar ve hamur homojenleşir. Bu aşama atlanırsa camda \'tohum\' denilen kabarcıklar kalır.'),
  ('Bir cam şişeye yeşil renk verilmesinde hangi katkı yaygın olarak etkilidir?', 'Demir oksit', ['Kobalt oksit', 'Altın klorür', 'Kalay oksit'], 'Düşük saflıkta kumdaki demir bileşikleri cama yeşilimsi bir ton verir; şişe camı bu yüzden çoğu zaman yeşildir.'),
  ('Murano ustalarının Çin porseleni taklidi için ürettiği opak, süt beyazı camın adı nedir?', 'Lattimo', ['Cristallo', 'Calcedonio', 'Avventurina'], '\'Lattimo\' (süt) adı rengini anlatır. Opak beyaz cam, 15. yüzyıldan itibaren kâse ve şişelerde porselen görünümü vermek için kullanılmıştır.'),
  ('Camın içine çok sayıda renkli çubuk kesitinin gömülmesiyle çiçek benzeri desenler veren, adı \'bin çiçek\' anlamına gelen teknik hangisidir?', 'Millefiori', ['Reticello', 'Latticino', 'Sommerso'], 'Renkli kamışlar bir araya getirilip çekilir, kesitleri alınır ve kabın cam gövdesine yerleştirilir. Her kesit küçük bir çiçek gibi görünür.'),
  ('Murano\'da bakır parçacıklarının cam içinde kristalleşmesiyle elde edilen, altın pul gibi pırıldayan cam türü hangisidir?', 'Aventurin', ['Lattimo', 'Fumé', 'Opalin'], 'Aventurin, içindeki mikroskobik bakır kristallerinin ışığı yansıtmasıyla parıldar. Efsaneye göre ilk kez kazara bulunmuş olduğundan \'rastlantı\' sözcüğünden adını almıştır.'),
  ('Fransa\'nın Lorraine bölgesinde 1764\'te kurulan ve kristal avizeleri ile sofra takımlarıyla tanınan cam markası hangisidir?', 'Baccarat', ['Daum', 'Orrefors', 'Venini'], 'Baccarat, Fransız kraliyetinin ve birçok ülke sarayının avize ve kadehlerini üretmiştir; kristal markası olarak hâlâ bilinir.'),
  ('Nancy Okulu\'nun (École de Nancy) kurucusu olan, doğadan alınmış bitki ve böcek temalarını asitle dağlanmış katmanlı camlara işleyen Fransız sanatçı kimdir?', 'Émile Gallé', ['René Lalique', 'Josef Hoffmann', 'Dominick Labino'], 'Gallé, 1901\'de kurulan Nancy Okulu\'nun başkanıdır. Vazolarına şiir dizeleri yazarak \'konuşan cam\' (verrerie parlante) fikrini geliştirmiştir.'),
  ('Nancy\'de 1878\'de kurulan ve pâte de verre ile gravürlü cam eserleriyle tanınan aile firması hangisidir?', 'Daum', ['Steuben', 'Moser', 'Venini'], 'Daum kardeşler Art Nouveau döneminde Gallé ile birlikte Nancy\'nin cam sanatını belirlemiş, aile firması bugün de sürmektedir.'),
  ('1903\'te New York\'un Corning kentinde kurulan Steuben Glass\'ın kurucu tasarımcısı kimdir?', 'Frederick Carder', ['Harvey Littleton', 'Carlo Scarpa', 'Dale Chihuly'], 'Frederick Carder, İngiliz asıllı bir cam ustasıdır. Steuben\'de \'Aurene\' gibi gökkuşağı yansımalı camlar geliştirmiştir.'),
  ('1962\'de Toledo Müzesi\'nde Harvey Littleton ve Dominick Labino\'nun düzenlediği atölyeler, camcılıkta hangi akımın başlangıcı sayılır?', 'Stüdyo cam hareketi', ['Art Nouveau camcılığı', 'Fabrika üretimi kristal', 'Vitray restorasyonu'], 'Küçük fırınların tek sanatçının atölyesine sığabilmesi, camı sanayiden çıkarıp bireysel sanat hâline getirmiştir; bu akıma \'stüdyo cam\' denir.'),
  ('Dale Chihuly\'nin 1971\'de kurulmasına katkıda bulunduğu, Amerikan stüdyo cam hareketinin eğitim merkezi olan okul hangisidir?', 'Pilchuck Cam Okulu', ['Bauhaus', 'Black Mountain College', 'Cranbrook'], 'Washington eyaletinde kurulan Pilchuck, cam sanatçılarının yetişmesinde etkili bir merkez olmuş; Chihuly\'nin renkli organik biçimli işleri ise geniş kitlelerce tanınmıştır.'),
  ('Dünyanın en kapsamlı cam koleksiyonuna sahip olan, 1951\'de New York\'un Corning kentinde açılan müze hangisidir?', 'Corning Cam Müzesi', ['Toledo Resim Müzesi', 'Murano Cam Müzesi', 'Kunstgewerbemuseum'], 'Corning Cam Müzesi, yaklaşık 3.500 yıllık cam tarihini kapsayan sergileri ve cam yapım gösterileriyle tanınır.'),
  ('Bir Boğaz yalısında sergilenen, opalin zemin üzerine ince spiral iplik süslü Osmanlı cam eşyasına hangi ad verilir?', 'Çeşm-i bülbül', ['Revzen', 'Telkâri', 'Kündekâri'], 'Çeşm-i bülbül (\'bülbül gözü\'), Beykoz\'da 19. yüzyılda üretilmiş, opal cam üzerine ince sarmal iplik süslemeli eşyaların adıdır.'),
  ('18-19. yüzyılda Osmanlı cam ve billur üretimiyle tanınan, Boğaz\'ın Anadolu yakasındaki hangi semt koleksiyonculukta \'işi\' ekiyle anılan cam grubuna adını vermiştir?', 'Beykoz', ['Eminönü', 'Kadıköy', 'Üsküdar'], 'Beykoz\'da çalışan atölyeler, çeşm-i bülbül ve renkli cam şişe ve şerbet takımlarıyla ünlenmiş, koleksiyoncuların aradığı \'Beykoz işi\' camları üretmiştir.'),
  ('Seramik türleri arasında en düşük sıcaklıkta pişen, gözenekli ve su geçirgen olup çoğunlukla sırla kaplanarak kullanılan grup hangisidir?', 'Çanak çömlek (earthenware)', ['Porselen', 'Taş hamur (stoneware)', 'Kemik porselen'], 'Çanak çömlek yaklaşık 1000-1150 °C\'de pişer ve gözenekli kalır; su geçirmezlik için sır gerekir. Porselen ise en yüksek ısıda pişen, camsı ve yarı saydam gövdedir.'),
  ('Porselen hamurunun temel bileşeni olan, beyaz kuvvetli kil minerali hangisidir?', 'Kaolin', ['Bentonit', 'Hematit', 'Gips'], 'Kaolin, Çin\'de Kao-ling (Gaoling) tepesinden adını alır. Porselen kaolin, feldispat ve kuvarsın karışımından yapılır.'),
  ('Fransa\'da Louis XV\'in himayesindeki Vincennes manufakturası 1756\'da hangi kente taşınarak ünlü bir kraliyet porselen atölyesine dönüşmüştür?', 'Sèvres', ['Limoges', 'Nancy', 'Lyon'], 'Sèvres manufakturası yumuşak hamurlu porselenin zarif renkleri ve altın yaldızlarıyla Avrupa saraylarına örnek olmuş; Madame de Pompadour bu atölyeyi desteklemiştir.'),
  ('Seramik yapımında çömlekçi çarkında şekillendirmeyi ifade eden \'atma\' (throwing) işleminde ustanın ilk yaptığı iş nedir?', 'Kil topunu çarkın tam merkezine yerleştirmek', ['Camı fırına yerleştirmek', 'Sırı fırçayla sürmek', 'Kalıba alçı dökmek'], 'Çarkta merkezleme yapılmazsa kap dengesiz ve eğri olur; usta önce kili çark merkezine oturtur, sonra içini açar ve çeperleri yükseltir.'),
  ('Kili uzun ince ruloya çevirip üst üste sarmal biçiminde yükselterek kap yapmak, hangi eski el işçiliği yöntemidir?', 'Rulo (coil) tekniği', ['Plaka tekniği', 'Çarkta atma', 'Pres kalıp'], 'Rulo tekniğinde sürekli sarılan kil iplikler birleştirilip yüzeyi düzeltilir. Bu yöntem çömlekçi çarkı bilinmeden önce de kullanılmıştır.'),
  ('Seramik yüzeyinde pişmeden önce sıvı kilin (slip) dekor olarak sürülmesinde kullanılan yönteme Fransızca\'da ne ad verilir?', 'Barbotine', ['Kintsugi', 'Cuerda seca', 'Lüster'], 'Barbotine, sıvı kil (slip) ile kabartmalı ya da yüzeye sürülen süsleme yöntemidir; çömlekçilikte uzun süredir kullanılır.'),
  ('Japon seramik geleneğinde odun yakıtlı, yamaç boyunca uzanan uzun fırına ne ad verilir?', 'Anagama', ['Raku', 'Bizen', 'Seto'], 'Anagama (\'mağara fırın\'), yamaca yatay uzanan tek odacıklı fırındır. Odun külü eriyip eşyaların üzerine doğal sır olarak yerleşir.'),
  ('Fırın içinde kapların alevden ve kül etkisinden korunması için içine yerleştirildikleri, ateşe dayanıklı kapalı kutulara ne ad verilir?', 'Saggar', ['Pontil', 'Marver', 'Muffle'], 'Saggar (kapsül), eşyayı kül ve alevden korur; özellikle porselen pişirimi sırasında kapları temiz tutmak için kullanılır.'),
  ('Bir porselen çay fincanı ışığa tutulduğunda parmak gölgesi içinden belli belirsiz görünüyor. Bu özellik porselenin hangi niteliğidir?', 'Yarı saydamlık', ['Gözeneklilik', 'Esneklik', 'Manyetik özellik'], 'Yüksek ısıda pişen porselen camsılaşır ve ince cidarlı hâlde ışığı geçirir; bu özellik çanak çömlek ve taş hamurda bulunmaz.'),
  ('Bir tabağın yüzeyindeki incecik çatlak ağına seramikçiler ne ad verir?', 'Craquelé', ['Slumping', 'Temperleme', 'Reduksiyon'], 'Hamur ile sırın farklı büzülmesi yüzeyde ince çatlaklar oluşturur. Bazı Çin seramiklerinde bu etki bilerek arandı ve güzellik sayıldı.'),
  ('Çin\'de Tang Hanedanı mezarlarında bulunan at ve deve figürlerini renklendiren, yeşil, kehribar ve kremden oluşan kurşun sırlı üç renkli seramiğe ne ad verilir?', 'Sancai', ['Famille rose', 'Ding', 'Kintsugi'], 'Sancai (\'üç renk\'), Tang döneminde ölülerle birlikte gömülen mingqi (mezar eşyası) figürlerinde kullanılmıştır; Ipek Yolu ticaretini canlandıran deve kervanları da yaygın konudur.'),
  ('Çin\'de kobalt mavisiyle beyaz porselen üzerine yapılan sıraltı boyamanın ihraç yoluyla yayıldığı ve Yuan döneminde başlayıp Ming\'de zirve yapan seramik türü hangisidir?', 'Mavi-beyaz porselen', ['Sancai', 'Seladon', 'Raku'], 'Mavi-beyaz porselenin kobaltı ilk dönemde İran\'dan getirilmiş; ürünler İslam dünyasına ve Avrupa\'ya ihraç edilerek İznik ve Delft gibi merkezlerin taklitlerine ilham vermiştir.'),
  ('Japonya\'da 1610\'lu yıllarda Arita yakınlarında kaolin bulunmasında rol oynayan ve Japon porselenini başlatan Koreli çömlekçi kimdir?', 'Yi Sam-pyeong', ['Hon\'ami Koetsu', 'Kitaōji Rosanjin', 'Bernard Leach'], 'Koreli çömlekçiler Hideyoshi\'nin Kore seferleri sırasında Japonya\'ya getirilmiş; Yi Sam-pyeong\'un 1616 dolayında Arita\'da kaolin bulmasıyla Japon porselen üretimi başlamıştır.'),
  ('Japon Arita porselenleri arasında, kobalt mavisi, demir kırmızısı ve altın yaldızın yoğun kullanıldığı, Avrupa\'ya ihracat limanının adıyla anılan tür hangisidir?', 'Imari', ['Bizen', 'Satsuma', 'Hagi'], 'Arita\'da üretilen bu porselenler İmari limanından gönderildiği için \'Imari\' adını almıştır; koyu mavi, kırmızı ve yaldızlı bezemeleri Avrupa\'da çok sevilmiştir.'),
  ('Antik Yunan\'da şarap ve suyu karıştırmak için kullanılan geniş ağızlı büyük kabın adı nedir?', 'Krater', ['Lekythos', 'Hydria', 'Kylix'], 'Yunanlılar şarabı suyla karıştırarak içerdi. Krater bu karışım için büyük bir kaptı; kylix içki kâsesi, hydria su kabı, lekythos ise yağ şişesiydi.'),
  ('Girit\'te Minos uygarlığının ince cidarlı, polikrom bezemeli seramikleri hangi adla bilinir?', 'Kamares seramiği', ['Terra sigillata', 'Geometrik stil', 'Yaşlı Dipylon vazoları'], 'Kamares seramiği, adını Ida Dağı\'ndaki Kamares Mağarası\'ndan alır. Yumurta kabuğu inceliğindeki duvarlar ve bitkisel motifler başlıca özellikleridir.'),
  ('Rönesans İtalya\'sında Urbino\'da, tabak yüzeyine tablo gibi tarihî ve mitolojik sahnelerin işlendiği majolika türüne ne ad verilir?', 'Istoriato', ['Sancai', 'Imari', 'Kintsugi'], 'Istoriato (\'hikâyelenmiş\'), tabak yüzeyini bir tuval gibi kullanan anlatı resmidir. Genellikle gravür kaynaklardan uyarlanmış sahneler içerir.'),
  ('Dokumada çözgü ipliğinin yönü nasıldır?', 'Tezgâh boyunca, kumaşın uzunluğunca uzanır', ['Kumaşın eni boyunca ilerler ve mekikle çözgülerin arasından taşınır', 'Rastgele yönlü, tezgâha gerilmeden doğrudan sarılan iplik takımıdır', 'Her zaman çapraz'], 'Çözgü, tezgâha gerilen boyuna iplik takımıdır; atkı ise bu ipliklerin arasından enine geçirilir. Kumaş bu iki iplik takımının kesişmesiyle oluşur.'),
  ('Ek atkı kullanılarak yüzeyde kabarık, çoğu kez altın ve gümüş iplikli desenler elde edilen ağır kumaşa ne ad verilir?', 'Brokar', ['Şifon', 'Kanvas', 'Krep'], 'Brokarda ek atkılar zemin kumaşın üzerinde ayrı bir desen katmanı oluşturur; saray giysilerinde, dinî giysilerde ve döşemede kullanılmıştır.'),
  ('Kot pantolon kumaşı olan \'denim\', adını hangi kentten almıştır?', 'Nîmes', ['Nancy', 'Nantes', 'Nice'], '\'Serge de Nîmes\' kumaşı, Fransa\'nın Nîmes kentinde dokunan dimi bağlantılı dayanıklı kumaştır; adı kısalarak \'denim\' olmuştur.'),
  ('Çin\'de dut yaprağıyla beslenen ve kozası tek iplik olarak çözülerek ipeğe dönüştürülen böceğin bilimsel adı nedir?', 'Bombyx mori', ['Apis mellifera', 'Lymantria dispar', 'Papilio machaon'], 'Bombyx mori, evcilleştirilmiş ipek böceğidir. Bir koza yaklaşık bir kilometre uzunluğunda kesintisiz bir ipek lifi verir.'),
  ('Hindistan\'ın Hint vadisi uygarlığında çok erken dönemlerde işlenmeye başlanan bitkisel lif hangisidir?', 'Pamuk', ['Keten', 'Yün', 'Kenevir'], 'Pamuk Mohenjo-daro gibi Hint vadisi yerleşimlerinde MÖ 3. binyıldan beri kullanılmıştır; sonraki dönemlerde Avrupa tekstilini etkileyen baskılı Hint pamuklularının temelini oluşturur.'),
  ('Mısır mumyalarının sarılmasında yaygın biçimde kullanılan, bitki saplarından elde edilen lif hangisidir?', 'Keten', ['Pamuk', 'Yün', 'İpek'], 'Keten (Linum usitatissimum) lifleri Mısır\'da ince dokuma bezlere dönüştürülmüştür; mumya sargılarının yanı sıra rahip giysileri de keten dokunurdu.'),
  ('İlk tamamen sentetik lif olarak kabul edilen ve 1935\'te Wallace Carothers\'ın DuPont\'ta geliştirdiği malzeme hangisidir?', 'Naylon', ['Viskon', 'Asetat', 'Likra'], 'Naylon bir poliamittir; ilk ticari ürünü 1938\'de diş fırçası kılları, 1940\'ta kadın çorapları olmuştur. Viskon ise doğal selülozdan elde edilen yarı sentetik bir liftir.'),
  ('Bir kumaşın ışığa tutulduğunda iplikler arasında düzenli kare açıklıklar görülüyorsa bu bağlantı hangisidir?', 'Bez bağlantı', ['Saten', 'Dimi', 'Jakar'], 'Bez bağlantıda atkı ve çözgü bir üst bir alt biçiminde kesişir; ışık, kesişim aralıklarından kare gözler olarak geçer.'),
  ('Endonezya\'nın Cava adasıyla özdeşleşen, kumaşa sıcak mumla çizilen alanların boyayı reddetmesine dayanan geleneksel desenleme tekniği hangisidir?', 'Batik', ['Ikat', 'Damask', 'Jakar'], 'Mumla kapatılan bölgelere boya girmez; kumaş boyandıktan sonra mum eritilerek çıkarılır. UNESCO, Endonezya batiğini 2009\'da somut olmayan kültürel miras olarak tanımıştır.'),
  ('Kumaşın katlanıp bağlanarak ya da sıkıştırılarak boyanması ilkesine dayanan Japon geleneği hangisidir?', 'Shibori', ['Sashiko', 'Kintsugi', 'Raku'], 'Shibori, kumaşı büküp, bağlayıp ya da tahta parçaları arasında sıkıştırarak boyama yöntemidir; çoğunlukla indigo ile uygulanır ve çok çeşitli desenler verir.'),
  ('Kökboya (Rubia tinctorum) bitkisinin kökünden elde edilen ve halı ile kumaşlarda yaygın kullanılan renk hangisidir?', 'Kırmızı', ['Mavi', 'Sarı', 'Mor'], 'Kökboya, kök dokusundaki alizarin maddesiyle kırmızı boya verir. Yüzyıllarca Anadolu halıcılığının temel kırmızısı olmuştur.'),
  ('Orta Asya\'da gelinlerin çeyizi olarak hazırlanan, büyük çiçek ve güneş-ay motifli iri nakışlı örtülere ne ad verilir?', 'Suzani', ['Kantha', 'Sashiko', 'Bandhani'], 'Suzani, Farsça \'iğne\' sözcüğünden gelir; Özbekistan ve Tacikistan\'da düğün yatağı örtüsü olarak işlenirdi.'),
  ('Siyah ipekten yapılan ince bobin danteliyle tanınan ve adını bir Fransız kasabasından alan dantel türü hangisidir?', 'Chantilly', ['Honiton', 'Torchon', 'Valenciennes'], 'Chantilly dantelleri siyah ipekle yapılır; 18. yüzyılda Fransız sarayında ve 19. yüzyılda Avrupa moda dünyasında ünlenmiştir.'),
  ('Antik Yunan\'da eğri, dışa açılan kılıç biçimli bacakları ve kavisli sırt desteğiyle zarif sandalye tipinin adı nedir?', 'Klismos (Yunan sandalyesi)', ['Savonarola (Rönesans sandalyesi)', 'Windsor (İngiliz çubuk sırtlı sandalye)', 'Cabriole (Barok kıvrık bacaklı sandalye)'], 'Klismos MÖ 5. yüzyılda vazo resimlerinde sık görülür; 18-19. yüzyılda neoklasik mobilyada yeniden canlandırılmış ve Empire ile Regency\'yi etkilemiştir.'),
  ('Orta Çağ\'da hem oturak hem saklama hem de taşıma işlevi gören, yaygın ve en temel mobilya parçası hangisiydi?', 'Sandık', ['Yazı masası', 'Şifonyer', 'Vitrinli büfe'], 'Gezgin soylular ve tüccarlar sandığı taşırdı; kapağı oturağa, masaya ya da yatağa dönüşebilirdi. Bu nedenle sandık Orta Çağ evinin merkezî eşyası sayılırdı.'),
  ('Gotik ve erken Rönesans ahşap panellerinde görülen, kıvrılmış kumaş ya da perde pilelerini andıran oyma bezemeye ne ad verilir?', 'Linenfold', ['Marküteri', 'Parketri', 'Tessera'], 'Linenfold (keten kıvrımı) 15. yüzyılda Kuzey Avrupa\'da ortaya çıkıp duvar kaplamasında ve dolap kapaklarında yaygınlaşmıştır.'),
  ('Rönesans İtalya\'sında evlilik çeyizi olarak hazırlanan, boyalı ya da oymalı büyük sandığa ne ad verilir?', 'Cassone', ['Credenza', 'Tavolo', 'Armadio'], 'Cassone, gelinin çeyizini taşımak için yaptırılan değerli bir sandıktı; yüzeyleri çoğunlukla Botticelli gibi ünlü ressamların atölyelerinde boyatılırdı.'),
  ('X biçimli bacakları sayesinde katlanabilen, Floransa Rönesans\'ının tipik koltuklarından biri olan mobilya hangisidir?', 'Savonarola sandalyesi', ['Klismos', 'Barcelona koltuğu', 'Bergère'], 'Savonarola sandalyesi, bir araya gelen eğri tahta şeritlerle yapılmış katlanır koltuktur; adını Floransalı rahipten almıştır, ancak onun zamanından önce de kullanılıyordu.'),
  ('Fransız mobilyasında bronz süslemelerin altın yaldızla kaplanmasına ne ad verilir?', 'Ormolu', ['Gesso', 'Patine', 'Ebru'], 'Ormolu, cıvalı yaldızlama ile bronza altın kaplayarak mobilya ve saat yüzeylerinde parıltı veren süslemedir; XV. ve XVI. Louis döneminde zirveye ulaşmıştır.'),
  ('18. yüzyıl İngiltere\'sinde köy ve han mobilyası olarak başlayıp yaygınlaşan, çubuklu sırtlı ve ahşap oturaklı sandalye hangi adla anılır?', 'Windsor sandalyesi', ['Barcelona sandalyesi', 'Thonet no. 14', 'Klismos'], 'Windsor sandalyesinde bacaklar ve çubuklar doğrudan kalın bir tahta oturağa geçirilir; kırsal İngiltere\'de başlayıp Amerika\'ya da yayılmıştır.'),
  ('Ahşap parçaların kesilip bir yüzeye yapıştırılarak resimli ya da geometrik bezeme oluşturulmasına ne ad verilir?', 'Marküteri', ['Kabartma', 'Barbotin', 'Lake'], 'Marküteri\'de farklı renkli ahşap, fildişi ya da sedef parçaları kesilip bir zemin üzerine yerleştirilir. Kaplama (veneer) üzerinde yapılır.'),
  ('Mobilya yapımında iki parçayı birbirine geçirmek için bir parçanın ucunda çıkıntı, diğerinde oyuk açılan birleşime ne ad verilir?', 'Zıvana (mortise and tenon)', ['Kırlangıç kuyruğu (yelpaze biçimli geçmeli dişli birleşim)', 'Parmak geçme (uçları dişli ve birbirine geçen birleşim)', 'Lamel'], 'Zıvana, kapı, masa ve sandalye çerçevelerinin en eski ve güçlü birleşimidir; antik Mısır\'dan bu yana kullanılır.'),
  ('Bir ağaç kütüğünden kesilmiş ince ahşap tabakalarının daha ucuz bir gövdeye yapıştırılmasına ne denir?', 'Kaplama (veneer)', ['Parke (zemine döşenen küçük ahşap parçalar)', 'Oyma (ahşabın kesici aletlerle kabartma işlenmesi)', 'Tornalama (ahşabın dönen tezgâhta şekillendirilmesi)'], 'Kaplama, pahalı ve güzel damarlı ağaçları ekonomik kullanır; Boulle, Riesener ve diğer ebenistler dönemin lüks dolaplarını kaplamayla yapmıştır.'),
  ('Arne Jacobsen\'in 1952\'de tasarladığı, kontrplak kabuğuyla üç bacaklı olarak üretilen ve adı bir böcek türünden gelen sandalye hangisidir?', 'Karınca (Ant)', ['Yumurta (Egg; aynı tasarımcının 1958 tarihli kabuk koltuğu)', 'Lale (Tulip)', 'Panton (tek parça plastik, S biçimli sandalye)'], 'Ant sandalyesi, tek parça kıvrık kontrplak gövde ve ince çelik ayaklarıyla istiflenebilir ve ucuzdur; Danimarka modern tasarımının ikonlarındandır.'),
  ('Charles ve Ray Eames\'in 1956\'da tasarladığı, kıvrımlı kontrplak kabuklu ve deri döşemeli koltuğa ne ad verilir?', 'Lounge Chair ve Ottoman', ['Tulip', 'Ant', 'Barcelona'], 'Eames Lounge Chair, İngiliz kulüp koltuklarının konforunu modern üretimle birleştirmeyi amaçlamış, Herman Miller tarafından üretilmiştir.'),
  ('Türk evinde duvar boyunca uzanan, üzerine minder ve yastık konularak oturulan sabit oturma düzenine ne ad verilir?', 'Sedir', ['Rahle', 'Yüklük', 'Sandık'], 'Sedir (divan), odanın ana oturma elemanıdır; Türk evinde bu düzen, mobilya yerine dolap, yüklük ve niş kullanılmasıyla birlikte ortaya çıkmıştır.'),
  ('Türk evinde yatak ve yorganların gündüz saklandığı, duvar içine gömülü büyük dolaba ne ad verilir?', 'Yüklük', ['Cumba', 'Hayat', 'Şahnişin'], 'Yüklük, sabah yataklar toplanarak saklanır; böylece oda gündüz oturma, geceleri yatma odasına dönüşür. Bu çok işlevli yapı Türk evinin önemli özelliğidir.'),
  ('Türk evlerinde sokağa doğru çıkma yapan, pencereli kapalı çıkıntı bölümüne ne ad verilir?', 'Cumba', ['Hayat', 'Sofa', 'Gusülhane'], 'Cumba, üst katın sokağa taşan pencereli bölümüdür; hem daha geniş görüş hem de iç mekâna ışık ve mahremiyet sağlar.'),
  ('Pembe (roz) altının rengini veren alaşım katkısı hangi metaldir?', 'Bakır', ['Gümüş', 'Paladyum', 'Platin'], 'Altına belirgin oranda bakır karıştırıldığında pembemsi kırmızı bir renk oluşur; bakır oranı arttıkça renk koyulaşır.'),
  ('Bir mücevher taşının ağırlığını ölçmede kullanılan 1 karat kaç grama eşittir?', '0,2 gram', ['1 gram', '0,02 gram', '2 gram'], 'Taşlarda 1 karat 200 miligramdır; bu yüzden beş karatlık bir taş 1 gram gelir. Altın ayarındaki \'karat\' ile karıştırılmamalıdır.'),
  ('Mücevherde taşın çevresini kaplayan metal çerçeveye ne ad verilir?', 'Bezel', ['Tırnak', 'Pavé', 'Galerie'], 'Bezel yerleştirmesi, taşı çevreleyen sürekli metal kenarla sıkıca tutar; taş korunur ancak ışık girişi azalır. En eski mıhlama biçimlerinden biridir.'),
  ('Mücevherde küçük taşların yüzeyi kaplayacak kadar sıkı dizilip taşlar arasında metalin neredeyse görünmediği mıhlama biçimine ne ad verilir?', 'Pavé (döşeme)', ['Bezel', 'Kanal (channel)', 'Tırnak'], 'Pavé, \'döşenmiş\' anlamına gelir; küçük taşlar çok sık biçimde yerleştirilir ve metal taşların altında kaybolur; yüzey pırıltılı görünür.'),
  ('Mohs sertlik ölçeğinde 10 değerini alan mineral hangisidir?', 'Elmas', ['Korindon', 'Kuvars', 'Topaz'], 'Mohs ölçeği 1\'den 10\'a kadar sertliği sıralar; elmas en sert minerali olarak 10, korindon (yakut ve safir) 9\'dur.'),
  ('Zümrüt hangi mineralin yeşil çeşididir?', 'Beril', ['Korindon', 'Kuvars', 'Topaz'], 'Zümrüt, krom ve vanadyum izleri nedeniyle yeşil renkli berildir. Akuamarin ise aynı mineralin mavi çeşididir.'),
  ('Kehribar, kuyumculukta kullanılan hangi tür malzemedir?', 'Fosilleşmiş ağaç reçinesi', ['Volkanik kökenli, sert ve camsı bir mineral olması', 'Deniz mercanı', 'Kil ürünü'], 'Kehribar, milyonlarca yıl önceki ağaç reçinesinin fosilleşmesiyle oluşur; içinde böcek ve bitki parçaları kalabilir. Baltık kıyıları ünlü kaynaklarındandır.'),
  ('Karadeniz kuzeyi bozkırlarında yaşayan Skitlerin altın işçiliğinde belirgin olan üsluba ne ad verilir?', 'Hayvan üslubu', ['Soyut geometrik üslup', 'Bitkisel arabesk', 'Gotik tarz'], 'Skit kuyumcuları geyik, panter ve kartal gibi hayvanları dövme altın üzerinde dinamik biçimde işlemişlerdir; bu hayvan üslubu Orta Asya sanatını da etkilemiştir.'),
  ('1847\'de Paris\'te kurulan, platin ile elmasın \'garland\' (çelenk) üslubunda kullanılmasıyla ünlenen ve VII. Edward\'ın \'mücevhercilerin kralı\' dediği mücevher evi hangisidir?', 'Cartier', ['Tiffany', 'Bulgari', 'Georg Jensen'], 'Cartier, Edward VII\'nin \'kralların mücevhercisi, mücevhercilerin kralı\' demesiyle ün kazanmış; 1917 tarihli Tank saati de en tanınmış tasarımlarındandır.'),
  ('Cartier\'nin 1920\'lerde Hint mücevherlerinden esinlenerek yakut, safir ve zümrüt gibi renkli taşları oyma biçimlerde bir araya getirdiği Art Deco serisine ne ad verilir?', 'Tutti Frutti', ['Mystery Set', 'Tank', 'Panthère'], 'Tutti Frutti (\'bütün meyveler\'), meyve, yaprak ve çiçek biçimine oyulmuş renkli taşların elmasla birleştirilmesiyle yapılan çok renkli mücevherlerdir.'),
  ('Tiffany & Co.\'nun 1845\'ten beri kullandığı özel renk hangisidir?', 'Turkuaz mavisi', ['Kızıl bakır rengi', 'Zümrüt yeşili', 'Altın sarısı'], 'Tiffany\'nin kutuları 1845 tarihli \'Blue Book\' kataloğunun kapağıyla başlayan turkuaz mavisi bir tonla bilinir; bu ton marka tescilidir.'),
  ('1884\'te Roma\'da küçük bir gümüşçü dükkânı olarak başlayan ve renkli taşlı, kabaşon kesimli cesur mücevherleriyle tanınan firmanın kurucusu hangi milletten bir ustaydı?', 'Yunan (Sotirios Voulgaris)', ['İtalyan (Roma doğumlu usta bir mücevhercinin torunu)', 'Fransız', 'Alman'], 'Epir\'den gelen Yunan gümüşçü Sotirios Voulgaris, Roma\'da açtığı dükkânı Bulgari adıyla bir mücevher imparatorluğuna dönüştürdü.'),
  ('Topkapı Sarayı Hazinesi\'ndeki 86 karatlık ünlü elmas, hangi adla bilinir?', 'Kaşıkçı Elması', ['Hope Elması', 'Cullinan Elması', 'Koh-i Noor'], 'Kaşıkçı Elması, çevresindeki 49 küçük elmasla süslü bir tarzda sergilenir; adının hikâyesi, bir kaşıkçı tarafından bulunmasına dayandırılır.'),
  ('Anadolu\'da gelinlik takılarında yaygın olan, geleneksel altın sikke dizilerinden yapılan boyun takısına ne ad verilir?', 'Gerdanlık', ['Mühre', 'Kakma', 'Gümüşlük'], 'Gerdanlık, kadınların boyuna taktığı geleneksel altın ya da gümüş süstür; düğün çeyizlerinin önemli bir parçasıdır ve sikkeler servet göstergesi sayılırdı.'),
  ('Japon lake sanatında kullanılan \'urushi\', hangi kaynaktan elde edilir?', 'Bir lak ağacının özsuyundan', ['Bir deniz salyangozunun salgısından', 'Pirinç nişastasından', 'Kömür katranından'], 'Urushi, lak ağacının kesilmiş gövdesinden akan özsudur; nemli ortamda oksidasyonla sertleşerek sert, suya dayanıklı parlak bir yüzey oluşturur.'),
  ('Lake yüzeyine yaş iken altın ve gümüş tozu serpilerek resim ya da desen yapılan Japon tekniğine ne ad verilir?', 'Maki-e', ['Raden', 'Shibori', 'Sashiko'], 'Maki-e \'serpilmiş resim\' demektir; ince fırça çizimi üzerine metal tozları serpilir, kuruyunca cilalanır. Japon lakesinin en prestijli süsleme tekniğidir.'),
  ('Çin\'de Neolitik çağdan itibaren değer verilen, Liangzhu kültürünün \'cong\' adlı törensel nesnelerinde işlenen malzeme hangisidir?', 'Yeşim', ['Altın', 'Fildişi', 'Kehribar'], 'Çin\'de yeşim, saflık ve ölümsüzlük simgesiydi; Liangzhu\'nun (MÖ 3000) yontulmuş yeşim cong\'ları bu geleneğin en eski örnekleri arasındadır.'),
  ('Batı\'da 17. yüzyılda, Doğu Asya lakesini taklit etmek için kullanılan reçine esaslı cilalı süsleme tekniğine ne ad verilir?', 'Japanning', ['Pâte de verre', 'Marküteri', 'Niello'], 'Japanning, ahşap ve metal üzerine reçine vernikle yapılan siyah ya da renkli parlak yüzeydir; ithal Japon lakesinin pahalılığı nedeniyle ortaya çıkmıştır.'),
  ('Hindistan\'ın Bidar kentine özgü, çinko ağırlıklı alaşım üzerine gümüş kakmalı siyahlaştırılmış metal işlerine ne ad verilir?', 'Bidri', ['Zardozi', 'Kalamkari', 'Tombak'], 'Bidri\'de siyah gövde, kimyasal işlemle yüzeye verilir ve parlak gümüş kakma desenler siyah zemin üzerinde öne çıkar.'),
  ('Londra\'daki 1851 Büyük Sergi\'nin (Great Exhibition) ardından kurulan ve bugün \'Victoria ve Albert Müzesi\' adıyla bilinen kurumun ilk adı nedir?', 'South Kensington Müzesi', ['Kensington Saray Galerisi', 'Albert Sanat Okulu', 'Hyde Park Tasarım Müzesi'], 'Sergiden elde edilen gelirle Henry Cole\'un önderliğinde 1852\'de kurulan müze, tasarımcıları ve imalatçıları eğitmek amacıyla örnek eşyalar topluyordu; 1899\'da bugünkü adını aldı.'),
  ('İskoçya\'da Charles Rennie Mackintosh\'un Glasgow\'da 1903\'te iç mekânını tasarladığı çay salonunun adı nedir?', 'Willow Tea Rooms', ['Peacock Room', 'Red House', 'Crystal Palace'], 'Mackintosh, çay salonunun cephesinden mobilyasına ve çatal bıçağına kadar her şeyi tasarlayıp tek bir bütün hâline getirmiştir; bu tavır \'bütünsel sanat yapıtı\' anlayışına örnektir.'),
  ('1907\'de Münih\'te mimar, tasarımcı ve sanayicileri bir araya getiren, Almanya\'da sanat ve sanayi ilişkisini kuran birlik hangisidir?', 'Deutscher Werkbund', ['Wiener Werkstätte', 'Omega Workshops', 'De Stijl'], 'Werkbund\'un hedefi, sanatçı, zanaatkâr ve sanayiciyi birleştirerek seri üretilmiş malların kalitesini artırmaktı; Bauhaus\'un habercisi sayılır.'),
  ('Bauhaus\'un dokuma atölyesinde yetişen ve 1927\'den sonra atölyenin yönetimini üstlenen kadın tasarımcı kimdir?', 'Gunta Stölzl', ['Anni Albers', 'Marianne Brandt', 'Charlotte Perriand'], 'Gunta Stölzl, Bauhaus\'un tek kadın ustası olarak dokuma atölyesini geliştirdi; geometrik ve renkli desenleri, modern tekstilin tarzını belirledi.'),
  ('1925 Paris sergisinde \'Bir Koleksiyoncunun Köşkü\'nü tasarlayan ve Art Déco mobilyasının en önemli ismi sayılan ebeniste kimdir?', 'Émile-Jacques Ruhlmann', ['Josef Hoffmann', 'Hector Guimard', 'Louis Majorelle'], 'Ruhlmann, ardıç, abanoz ve fildişi gibi nadir malzemelerle son derece zarif mobilyalar yapmıştır; Art Déco\'nun lüks yönünü temsil eder.'),
  ('Nancy\'de Art Nouveau mobilya üreten ve nilüfer çiçeği gibi bitkisel motifli gövdeleriyle bilinen ebeniste kimdir?', 'Louis Majorelle', ['Émile Gallé', 'Victor Horta', 'Henry van de Velde'], 'Majorelle, Nancy Okulu\'nun mobilya ustasıdır; kıvrımlı ahşap hatlarını bitkisel formlarla birleştiren dolap ve yataklar yapmıştır.'),
  ('Bir müzedeki Art Nouveau vazo ile Art Déco vazoyu karşılaştıran öğrenci hangi gözleme dayanarak ayrım yapabilir?', 'Birinde akıcı bitkisel çizgiler, diğerinde geometrik ve simetrik desenler görülür', ['İkisinde de aynı çizgiler vardır', 'Birinin plastikten diğerinin tahtadan yapıldığı görülür', 'Hiçbir fark yoktur'], 'Art Nouveau doğadan esinli kıvrımları, Art Déco ise keskin geometriyi ve simetriyi benimser.'),
  ('17-18. yüzyıl Avrupa dekorasyonunda Çin\'i hayalî ve zarif biçimde yorumlayan pagodalı, ejderhalı ve çaylı motifli süsleme modasına ne ad verilir?', 'Chinoiserie', ['Japonisme', 'Turquerie', 'Orientalisme'], 'Chinoiserie, Rokoko döneminde porselen, ipek ve lake ithalatının yarattığı hevesle gelişti; gerçek Çin sanatından çok Avrupalı hayal gücünü yansıtır.'),
  ('18. yüzyıl Avrupa\'sında Osmanlı giysileri, çadır ve lale motifleri gibi \'Türk\' öğelerini içeren dekorasyon modasına ne denir?', 'Turquerie', ['Chinoiserie', 'Japonisme', 'Grotesk'], 'Turquerie, Osmanlı\'ya duyulan merakın sanata ve eşyaya yansımasıdır; Mozart\'ın \'Türk Marşı\' ve \'Türk köşeleri\' bu modanın örnekleridir.'),
  ('1860\'lardan sonra Paris\'te ve Avrupa\'da Japon baskılarının ve eşyalarının tasarım ve resim üzerindeki etkisine ne ad verilir?', 'Japonisme', ['Chinoiserie', 'Turquerie', 'Primitivizm'], 'Japonisme, Japonya\'nın 1854\'te dışa açılmasıyla yayılan ukiyo-e baskılarının Manet, Monet, Whistler, Van Gogh ve dekoratif sanatçıları etkilemesi sürecidir.'),
  ('Korint sütun başlığında ve Barok-Neoklasik süslemelerde sık kullanılan, dikenli yaprak biçimli bitkisel motif hangisidir?', 'Akant (acanthus)', ['Palmet (hurma yaprağı biçimli yelpaze motifi)', 'Lotus (Mısır sanatının su çiçeği motifi)', 'Meander'], 'Akant yaprağı Antik Yunan\'dan beri Korint başlığıyla ve oymalı süslemeyle özdeşleşmiştir; kıvrılan yaprak biçimi mobilya ve metal işlerinde de uygulanır.'),
  ('Antik Yunan\'dan beri vazo, tapınak frizi ve mobilyada kullanılan, kesintisiz dik açılı kıvrımlardan oluşan şerit bezemesine ne denir?', 'Meander (Yunan anahtarı)', ['Rozet (dairesel, çiçek biçimli süsleme motifi)', 'Palmet', 'Akant'], 'Meander, adını Anadolu\'daki kıvrımlı Menderes Nehri\'nden alır; yinelenen dik kıvrımlar sonsuzluğu ve sürekliliği çağrıştırır.'),
  ('Barok ve Rokoko süslemelerinde sık görülen, kanatsız, çıplak çocuk figürlerine ne ad verilir?', 'Putto', ['Atlas', 'Karyatit', 'Kerub'], 'Putto (çoğulu putti), mitolojik ve dinî sahnelerde, mobilya, alçı ve tavan süslemelerinde çok görülen çıplak küçük çocuk figürüdür; kanatlıysa genellikle kerub (cherub) denir.'),
  ('Portekiz ve İspanya\'da duvar, taban ve cephe kaplamasında kullanılan, çoğunlukla mavi-beyaz boyalı sırlı çini karoya ne ad verilir?', 'Azulejo', ['Zellige', 'İznik çinisi', 'Delft karosu'], 'Azulejo, \'küçük cilalı taş\' anlamındaki Arapça kökenden gelir; Portekiz\'de kilise, istasyon ve konut cephelerini süslemiştir.'),
  ('Barok ve Rokoko iç mekânlarında tavan ve duvarlarda yüksek kabartma ve heykelsi süs için kullanılan malzeme hangisidir?', 'Alçı', ['Çelik levha ve perçinle birleştirilmiş sanayi parçaları', 'Cam', 'Plastik'], 'Stuko, alçı ve kireçten oluşan hamur olup kalıpla ya da elle biçimlendirilir; kubbe ve duvar yüzeylerinde ışık gölge oyunu yaratır.'),
  ('Bizans sanatında kutsal sahneleri ve ünlü kişileri işleyen, iki levhalı oyma fildişi nesneye ne ad verilir?', 'Diptik', ['Triptik', 'Poliptik', 'Kartuş'], 'Diptik, menteşeyle birleştirilmiş iki levhadır; konsüllerin göreve başladığında dağıttığı fildişi diptikler, geç Roma-Bizans sanatının dekoratif örnekleridir.'),
  ('Bir kuyumcu 20 gram ağırlığındaki 18 ayar altın bir yüzük yapmıştır. Bu yüzükte yaklaşık kaç gram saf altın vardır?', '15 gram', ['18 gram', '12 gram', '10 gram'], '18 ayar, 24 ayarın 18/24\'ü yani 3/4\'üdür. 20 × 3/4 = 15 gram saf altın bulunur.'),
  ('2,5 karatlık bir elmasın ağırlığı kaç gramdır? (1 karat = 0,2 gram)', '0,5 gram', ['0,25 gram', '2,5 gram', '5 gram'], 'Taş ölçüsünde 1 karat 0,2 gramdır. 2,5 × 0,2 = 0,5 gramdır.'),
  ('12 gram ağırlığındaki 22 ayar bir takıda yaklaşık kaç gram saf altın bulunur?', '11 gram', ['12 gram', '10 gram', '9 gram'], '22 ayar için saf altın oranı 22/24\'tür. 12 × 22/24 = 11 gramdır.'),
  ('Pişirildiğinde yüzde 10 küçülen bir kilden 30 cm çaplı tabak yapılırsa, pişmiş tabağın çapı kaç cm olur?', '27 cm', ['20 cm', '28 cm', '25 cm'], 'Küçülme sonrası çap, ilk çapın %90\'ıdır. 30 × 0,9 = 27 cm bulunur.'),
  ('Genişliği 150 cm olan bir tezgâha santimetrede 20 çözgü ipliği gerilirse toplam kaç çözgü ipi gerekir?', '3000', ['300', '1500', '750'], 'Toplam çözgü sayısı genişlik × sıklık = 150 × 20 = 3000 ipliktir.'),
  ('Pablo Picasso\'nun 1947\'den sonra seramik üretimine yöneldiği Fransız kasabası neresidir?', 'Vallauris', ['Limoges', 'Sèvres', 'Nîmes'], 'Picasso, Madoura atölyesinde binlerce seramik tabak ve vazo yaptı; kasaba bu çalışmalar sayesinde seramik sanatının önemli bir merkezi olarak bilinir.'),
  ('1890\'larda II. Abdülhamid\'in İstanbul\'da kurdurduğu, Avrupalı ustalarla çalışıp saray için porselen üreten imalathane hangisidir?', 'Yıldız Porselen Fabrikası', ['Hereke Fabrikası', 'Beykoz Cam Fabrikası', 'İznik Çini Atölyesi'], 'Yıldız Porselen Fabrikası, Sèvres ve Avrupa tekniklerini Osmanlı süsleme diliyle birleştirerek saray siparişlerini karşıladı; Osmanlı\'da porselen üretiminin başlangıcıdır.'),
  ('Vitray pencerede renkli cam parçalarını birbirine bağlayan, kesiti H ya da U biçimli esnek kurşun şeride ne ad verilir?', 'Came (kurşun çıta)', ['Marver (cam ustasının camı yuvarlayıp biçimlendirdiği düz tabla)', 'Pontil', 'Gesso'], 'Cam parçaları kurşun çıtaların oluklarına oturtulur, birleşim yerleri lehimlenir ve macunlanır; böylece pencere hafif ve esnek, ama sağlam olur.'),
  ('Vitrayda yüz ve giysi çizgileri gibi ayrıntıları vermek için cam yüzeyine uygulanıp fırınlanan koyu kahverengi-siyah boyaya ne ad verilir?', 'Grisaille', ['Gouache', 'Lüster', 'Mine'], 'Grisaille, metal oksit ve cam tozunun bağlayıcıyla karışımıdır; fırında cama kaynar. Fırça ve kazıma ile gölge ve çizgi elde edilir.'),
  ('Fransa\'da Lyon\'un ipek dokumacılarına verilen ve 1831\'deki ayaklanmayla tanınan ad nedir?', 'Canut', ['Maître', 'Ébéniste', 'Gobelin'], 'Canutlar, Lyon\'da ipek dokuyan işçilerdi; 1831\'de ücretlerin düşmesi üzerine ayaklanmışlar, sanayi dönemi işçi hareketlerinin erken örneklerinden birini oluşturmuşlardır.'),
  ('Osmanlı\'da altın ve gümüş iplikli zemin üzerine ipek desenli ağır saray kumaşına, özellikle Bursa\'da dokunmuş türü hangi adla anılır?', 'Kemha', ['Bürümcük', 'Kutnu', 'Şile bezi'], 'Kemha, ipek çözgü ve metal atkı ile dokunan, Bursa ve İstanbul\'da üretilen değerli bir saray kumaşıdır; padişah kaftanları ve yastık yüzlerinde görülür.'),
  ('18. yüzyılda Paris\'te bir kuyumcunun geliştirdiği, elmasa benzeyen parlak kurşun cam taklitlerine kuyumculukta hangi ad verilir?', 'Strass', ['Moissanit', 'Kübik zirkonya', 'Aventurin'], 'Bu taklit taş, onu geliştiren Georges Frédéric Strass\'ın adıyla anılır: yüksek kurşunlu cam taşlar gibi kesilip arkası folyoyla parlatılır. Bugün de kostüm takılarının temel taklit taşıdır.'),
  ('Kuyumculukta çekiçlenerek sertleşen ve çatlama riski taşıyan metali yeniden yumuşatmak için ısıtıp yavaş soğutma işlemine ne ad verilir?', 'Tavlama', ['Sertleştirme', 'Kaplama', 'Cilalama'], 'Metal çekiçlendikçe sertleşir ve çatlayabilir; ısıtılıp yavaş soğutulunca yeniden yumuşar. Bu işleme tavlama denir.'),
  ('Bir müşteri, 14 ayar ve 18 ayar altın bileziği karşılaştırıyor. İki bileziğin altın saflığı bakımından farkı nedir?', '18 ayar altın daha yüksek oranda saf altın içerir', ['14 ayar altın, 18 ayar altından daha yüksek oranda saf altın içerir', 'İkisi aynı oranda saf altın içerir', '18 ayar altın hiç altın içermez'], '18 ayar %75, 14 ayar yaklaşık %58,5 saf altın içerir; sayı büyüdükçe altın saflığı artar.'),
  ('Bir mücevher taşının üzerinde sıvı yağ ya da reçine ile çatlakların doldurulması işlemine kuyumculukta ne ad verilir?', 'Dolgu (yağlama) işlemi', ['Tavlama', 'Kaplama', 'Eritme'], 'Zümrütlerde çatlaklar yağ ya da reçineyle doldurulup taşın saydamlığı artırılır; bu işlem değer belirlerken açıklanmalıdır.'),
  ('Cam geri dönüşüm hakkında hangisi doğrudur?', 'Cam, kalite kaybı olmadan defalarca geri dönüştürülebilir', ['Cam bir kez geri dönüştürüldükten sonra tamamen kullanılamaz hâle gelir', 'Cam geri dönüştürülemez, ancak yeniden öğütülüp dolgu olarak kullanılabilir', 'Cam her dönüşümde yarı yarıya kalite kaybeder'], 'Kırık cam (cullet) eritilip yeni cam yapılabilir; camın yapısı bozulmadığından bu işlem sınırsız kez tekrarlanabilir.'),
  ('Gözü andıran desenli, mavi tonlu cam boncuğun Anadolu ve Akdeniz\'de yüzyıllardır kullanılmasının geleneksel nedeni nedir?', 'Nazardan korunma inancı', ['Boncukların para yerine kullanılması', 'Deniz yönünü bulma amacı', 'Sıcaktan korunma'], 'Göz biçimli cam boncuk, kıskanç bakışı geri çevirdiğine inanıldığı için kapılara, bebek giysilerine ve hayvanlara takılırdı; Antik çağlardan beri yaygındır.'),
  ('Ahşabın yaşının ağaç halkalarına bakılarak belirlenmesi yöntemine ne ad verilir?', 'Dendrokronoloji', ['Termolüminesans', 'Karbon-14 yöntemi', 'Spektroskopi'], 'Ağaç halkalarının kalınlığı yıllık iklim koşullarına göre değişir; bu desen bilinen takvimlere eşleştirilerek ahşap panonun ya da mobilyanın tarihi belirlenir.'),
  ('Bir müşteri, iki sandalye arasında seçim yapıyor: biri el oyması masif meşe, diğeri kalıpla basılmış plastik. Maliyet ve seri üretim bakımından hangisi öne çıkar?', 'Plastik sandalye, kalıp ve seri üretim nedeniyle daha ucuz olur', ['Meşe sandalye, çünkü ağaç ucuz ve işçilik zaman almaz', 'İkisi de aynı maliyettedir; çünkü ikisi de elle üretilir', 'İkisi de üretilemez'], 'Kalıpla üretim emek ve zamanı azaltır, birim maliyeti düşürür; el işçiliği ise pahalıdır ama benzersizdir.'),
  ('Mezopotamya\'da kil sözleşmelerin altına imza yerine yuvarlanarak basılan silindir biçimli süslü küçük taşlara ne ad verilir?', 'Silindir mühür', ['Skarabe', 'Pitos', 'Rhyton'], 'Silindir mühürler yumuşak çamura yuvarlandığında devamlı kabartma desen bırakır; hem mülkiyet damgası hem küçük taş oymacılığı sanatıdır.'),
  ('Etrüsk ustalarının ürettiği ve arkası süslü, önü parlak cilalı el aynaları hangi malzemedendi?', 'Bronz', ['Gümüş cam', 'Demir', 'Bakır cam'], 'Antik aynalar parlatılmış bronzdan yapılırdı; arka yüz çoğunlukla mitolojik sahnelerle oyulur ya da kabartılırdı.'),
  ('Antik Yunan\'da MÖ 4. yüzyıldan itibaren yaygın olan ve ziyafet sırasında uzanılan kanepeye ne ad verilir?', 'Kline', ['Klismos', 'Thronos', 'Diphros'], 'Kline, simpozyum ve cenaze törenlerinde yatarak yemek yenilen yüksek yataktır; Romalıların lectus\'u da buradan doğmuştur.'),
  ('Güçlü II. Augustus\'un 1717\'de Prusya Kralı\'na altı yüz asker verip karşılığında aldığı Çin porselen vazolarına verilen ad nedir?', 'Dragoon (Dragonder, süvari) vazoları', ['Peacock (Tavus kuşu) vazoları', 'Zafer vazoları', 'Lotus vazoları'], 'Augustus porseleni \'beyaz altın\' sayıyordu; 600 dragoon (süvari) karşılığında aldığı Çin vazoları \'Dragonervasen\' yani Dragoon vazoları adıyla anılır.'),
  ('İngiltere\'de 1790\'larda Çin tarzına benzetilerek yapılan ve sonra efsaneyle bağlanan mavi-beyaz tabak deseni hangisidir?', 'Willow (Söğüt) deseni', ['Blue Onion deseni', 'Peacock deseni', 'Rose Pompadour deseni'], 'Söğüt deseni Çin motifleriyle yapılmış İngiliz tasarımıdır; sevgililerin hikâyesi ise sonradan uydurulmuştur. Transfer baskıyla yüzbinlerce tabak üretilmiştir.'),
  ('Bir koleksiyoncu, bir porselen tabağın alt yüzeyinde çapraz iki mavi çizgi marka görüyor. Tabağın hangi manufakturaya ait olduğunu düşünmelidir?', 'Meissen', ['Sèvres', 'Royal Copenhagen', 'Wedgwood'], 'Çapraz mavi kılıçlar Meissen\'in damgasıdır; ancak taklit damgalar da yaygın olduğundan başka özelliklere de bakılmalıdır.'),
  ('Aynı kil ve aynı sır ile iki vazo üretiliyor; biri 1000 °C, diğeri 1280 °C\'de pişiriliyor. Hangisi daha sert ve camsı olur?', '1280 °C\'de pişen vazo', ['1000 °C\'de pişen vazo', 'İkisi de aynı olur; çünkü sır aynıdır', 'Pişme aşamasında kil bu ısıda tamamen erir ve vazo şeklini yitirir'], 'Yüksek ısıda kilin içindeki mineraller kısmen erir ve camsılaşır; sonuç daha sert, yoğun ve su geçirmez gövdedir.'),
  ('Japon çay seremonisinde kullanılan, el yapımı, hafif kusurlu ve sade çay kâselerinin ardındaki estetik anlayışı hangi kavram açıklar?', 'Wabi-sabi', ['Gesamtkunstwerk', 'Horror vacui', 'Chinoiserie'], 'Wabi-sabi, kusurlu, eksik ve geçici olanın güzelliğini yücelten bir anlayıştır; çay kâselerindeki asimetri ve doğal sır etkileri bu anlayışa uyar.'),
  ('Rusya\'da mavi-beyaz boyalı seramik geleneğiyle tanınan, Moskova yakınlarındaki köy ve bölge hangisidir?', 'Gzhel', ['Palekh', 'Khokhloma', 'Fedoskino'], 'Gzhel köylerinde kobalt mavisi çiçek motifleriyle boyanmış beyaz porselen ve çanak çömlek yapılır; mavi-beyaz görünümü Rus halk sanatının simgelerindendir.'),
  ('1905\'te Güney Afrika\'daki Premier Madeni\'nde bulunan ve ham hâlde 3106 karat gelen elmas hangi adla bilinir?', 'Cullinan', ['Hope', 'Kaşıkçı', 'Orlov'], 'Cullinan, bulunmuş en büyük mücevher kalitesindeki ham elmastır; 1908\'de Asscher tarafından kesilip parçalara ayrıldı. En büyük parçası İngiliz hükümdarlarının asasında yer alır.'),
  ('Türkçede yaygın olarak kullanılan \'pırlanta\' sözcüğü, hangi kesimli elmasa karşılık gelir?', 'Brilliant kesimli elmasa', ['Kabaşon kesimli taşa', 'Baget kesimli zümrüte', 'Ham elmasa'], 'Pırlanta sözcüğü İtalyanca \'brillante\'den gelir; parlak yüzeyli yuvarlak faset kesimli elmas anlamında kullanılır.'),
  ('Fransız kimyager Henri Moissan\'ın 1893\'te Arizona\'daki bir göktaşı krateri örneklerinde bulduğu, elmasa benzeyen mücevher taşı hangisidir?', 'Moissanit', ['Kübik zirkonya', 'Topaz', 'Safir'], 'Moissanit silisyum karbürdür; doğada çok nadir bulunur ve bugün laboratuvarda üretilip elmas alternatifi olarak satılır.'),
  ('İstanbul\'un Karadeniz kıyısındaki bir ilçesinin adıyla anılan, ince ve seyrek dokulu pamuklu kumaş hangisidir?', 'Şile bezi', ['Kutnu', 'Kemha', 'Buldan bezi'], 'Şile bezi, ince ve seyrek dokulu bir pamuklu kumaştır; el işi nakışları ve oya süslemeleriyle çeyiz ve giysi yapımında yaygın olarak kullanılmıştır.'),
  ('Topkapı Sarayı Müzesi, hangi koleksiyonuyla Çin dışındaki dünyanın en zengin kolleksiyonlarından birine sahiptir?', 'Çin porselenleri', ['Hint minyatürleri', 'Roma camları', 'İskit altınları'], 'Osmanlı sarayı, Fatih\'ten itibaren ve özellikle Yavuz ile Kanuni döneminde yoğun Çin porseleni toplamış; müzedeki bu koleksiyon Çin dışındakilerin en zengin örneklerindendir.'),
  ('Kumaş tasarımında bir desen biriminin düzenli aralıklarla tekrar etmesi için gereken birime ne ad verilir?', 'Rapport', ['Bordür', 'Medalyon', 'Moiré'], 'Rapport, desenin başlangıç ve bitiş noktasının birbirine uyduğu tekrar birimidir; baskı ve dokuma kumaşlarda, duvar kâğıdında temel kavramdır.'),
  ('İpek kumaşta ışıkta dalga ve su lekesi görünümü veren yüzeye ne ad verilir?', 'Moiré', ['Rapport', 'Jakar', 'Bordür'], 'Moiré, ribli bir kumaşın iki katının sıcak silindirler arasında bastırılmasıyla elde edilir; bastırılan rib yönleri ışığı farklı yansıtarak dalgalı bir görünüm verir.'),
  ('Halı ve kumaşlarda desenin kenar boyunca tekrarlanan şerit düzenine ne ad verilir?', 'Bordür', ['Medalyon', 'Rapport', 'Kartuş'], 'Bordür, ana alanı çerçeveleyen süs şeritleridir; çoğu halıda birkaç bordür bulunur: geniş ana bordür ve ince ara bordürler.'),
  ('Dekoratif tasarımda \'tüm yüzeye yayılmış, merkezsiz ve tekrarlayan düzen\' hangi adla anılır?', 'All-over (tüm yüzey) desen', ['Medalyon düzeni', 'Frizs düzeni', 'Simetrik portre'], 'All-over desen, motifin yüzeyde ritimle her yöne tekrarlandığı düzendir; Morris\'in duvar kâğıtları bunun tipik örnekleridir.'),
  ('Bir halı bordüründe yan yana duran aynı motifler arasında sürekli ritim görülmesi, tasarım ilkelerinden hangisini gösterir?', 'Tekrar ve ritim', ['Zıtlık', 'Asimetri', 'Perspektif'], 'Tekrar eden birimler gözü hareket ettirip ritim yaratır; bordürler bu ilkenin klasik uygulama alanıdır.'),
  ('Çömlekçi çarkının Mezopotamya\'da yaklaşık hangi dönemde kullanılmaya başlandığı kabul edilir?', 'MÖ 4. binyıl', ['MÖ 1. yüzyıl', 'MS 5. yüzyıl', 'MS 12. yüzyıl'], 'Çark, kabı elle biçimlendirmeye göre hızı ve düzgünlüğü artırdı; Mezopotamya\'daki Ur gibi yerleşimlerde MÖ 4. binyıldan itibaren kullanıldığı görülür.'),
  ('Bir seramik atölyesi çömlekçi çarkına geçtiğinde üretiminde hangi değişimi bekleriz?', 'Daha hızlı ve daha simetrik kap üretimi', ['Daha yavaş ve daha düzensiz kap üretimi', 'Hiçbir değişiklik olmaz', 'Kapların cam olması'], 'Çark, merkezkaç etkisiyle çeperleri düzgün ve eşit yükseltir; böylece kap biçimleri standartlaşır ve üretim hızlanır.'),
  ('Bir kuyumcu, el yapımı altın yüzüğün yüzeyinde hafif çekiç izleri görüyor. Bu iz hangi işçiliği düşündürür?', 'Dövme işçiliği', ['Lazer kesim', 'Kalıp dökümü yalnız', 'Elektrolitik kaplama'], 'Çekiç izleri yüzeyin elle dövüldüğünü gösterir; dökümde ise yüzey çoğunlukla kalıbın izlerini taşır.'),
];
